#import "PCTheme.h"
#import "PCLocalization.h"
#import "PCButtonCompat.h"
#import "PCPages.h"
#import "PCSupport.h"
@implementation PCOptionsPage
- (void)viewDidLoad {[super viewDidLoad];self.tableView.backgroundColor=PCCanvasColor();self.view.tintColor=PCTextColor();self.navigationController.navigationBar.tintColor=PCTextColor();self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=56;}
- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section {return self.options.count;}
- (NSString *)tableView:(UITableView *)tableView titleForFooterInSection:(NSInteger)section {return self.explanation;}
- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)indexPath {NSDictionary *item=self.options[indexPath.row];UITableViewCell *cell=[[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];cell.textLabel.text=item[@"title"];cell.textLabel.numberOfLines=0;cell.detailTextLabel.text=item[@"subtitle"];cell.detailTextLabel.numberOfLines=2;cell.imageView.image=[UIImage systemImageNamed:item[@"icon"]?:@"chevron.right"];cell.imageView.tintColor=PCTextColor();cell.textLabel.textColor=[item[@"danger"] boolValue]?UIColor.systemRedColor:PCTextColor();cell.accessoryType=[item[@"selected"] boolValue]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;return cell;}
- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)indexPath {[tableView deselectRowAtIndexPath:indexPath animated:YES];if(self.selectOption)self.selectOption(indexPath.row);PCHaptic(@"select");}
@end
@implementation PCTextEntryPage {UITextField *_field;}
- (void)viewDidLoad {[super viewDidLoad];self.view.backgroundColor=PCCanvasColor();_field=[UITextField new];_field.placeholder=self.fieldPlaceholder;_field.text=self.initialText;if(self.numeric)_field.keyboardType=UIKeyboardTypeNumberPad;_field.borderStyle=UITextBorderStyleRoundedRect;_field.translatesAutoresizingMaskIntoConstraints=NO;_field.font=[UIFont preferredFontForTextStyle:UIFontTextStyleBody];[self.view addSubview:_field];UILayoutGuide *g=self.view.safeAreaLayoutGuide;[NSLayoutConstraint activateConstraints:@[[_field.topAnchor constraintEqualToAnchor:g.topAnchor constant:24],[_field.leadingAnchor constraintEqualToAnchor:g.leadingAnchor constant:20],[_field.trailingAnchor constraintEqualToAnchor:g.trailingAnchor constant:-20],[_field.heightAnchor constraintEqualToConstant:48]]];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc] initWithTitle:self.submitTitle?:PCLocalized(@"创建") style:UIBarButtonItemStyleDone target:self action:@selector(create)];}
- (void)create {NSString *text=[_field.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(self.validationPattern&&![[NSPredicate predicateWithFormat:@"SELF MATCHES %@",self.validationPattern] evaluateWithObject:text]){self.navigationItem.prompt=PCLocalized(@"请输入 6 位数字");return;}if(text.length&&(!self.maximumLength||text.length<=self.maximumLength)&&self.submit)self.submit(text);}
@end
@implementation PCConfirmPage
- (void)viewDidLoad {[super viewDidLoad];self.view.backgroundColor=PCCanvasColor();UILabel *label=[UILabel new];label.text=self.message;label.numberOfLines=0;label.font=[UIFont preferredFontForTextStyle:UIFontTextStyleBody];UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem];if(@available(iOS 15.0,*)){UIButtonConfiguration *style=UIButtonConfiguration.filledButtonConfiguration;style.baseBackgroundColor=UIColor.systemRedColor;style.title=self.actionTitle?:PCLocalized(@"删除");button.configuration=style;}else{PCStyleButton(button,PCButtonFilled);button.backgroundColor=UIColor.systemRedColor;[button setTitle:self.actionTitle?:PCLocalized(@"删除") forState:UIControlStateNormal];}[button addTarget:self action:@selector(perform) forControlEvents:UIControlEventTouchUpInside];UIStackView *stack=[[UIStackView alloc] initWithArrangedSubviews:@[label,button]];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=24;stack.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:stack];UILayoutGuide *g=self.view.safeAreaLayoutGuide;[NSLayoutConstraint activateConstraints:@[[stack.topAnchor constraintEqualToAnchor:g.topAnchor constant:24],[stack.leadingAnchor constraintEqualToAnchor:g.leadingAnchor constant:20],[stack.trailingAnchor constraintEqualToAnchor:g.trailingAnchor constant:-20]]];}
- (void)perform {if(self.confirm)self.confirm();}
@end
